tape( 'the function quick returns when `M` or `N` is equal to 0', function test( t ) {
	var expectedA;
	var data;
	var S;
	var A;
	var C;

	data = LEFT_VAR_FWD;

	A = new Float64Array( data.A );
	C = new Float64Array( data.C );
	S = new Float64Array( data.S );

	expectedA = new Float64Array( data.A );

	dlasr( data.side, data.pivot, data.direct, 0, 0, C, data.strideC, data.offsetC, S, data.strideS, data.offsetS, A, data.strideA1, data.strideA2, data.offsetA );
	t.strictEqual( isAlmostEqual( A, expectedA, 1 ), true, 'returns expected value' );
	t.end();
});

